/* Purchase orders share stock identities with SOH and the existing Receive screen. */
/* Import matching only suggests existing stock; the admin reviews every line. */
window.purchaseOrderItemIdentity=item=>JSON.stringify([item.sku,item.colour||item.color,item.dimensions,item.lengthMm,item.unit,item.width,item.height,item.thickness,item.material].map(v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ')));
window.purchaseOrderStockKey=function(supplier,line){
 const normal=v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ');
 return JSON.stringify([supplier,line.sku,line.description,line.colour,line.dimensions,line.lengthMm||'',line.unit].map(normal));
};
window.isPurchaseOrderStock=item=>item.category!=='offcuts'&&!String(item.id||'').startsWith('offcut:');
window.matchPurchaseOrderLine=function(line,items,supplier='',references=[]){
 items=items.filter(window.isPurchaseOrderStock);
 const key=window.purchaseOrderStockKey(supplier,line),saved=references.filter(r=>r.key===key);
 const identity=item=>JSON.stringify([item.sku,item.colour||item.color,item.dimensions,item.lengthMm,item.unit,item.width,item.height,item.thickness,item.material].map(v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ')));
 const savedIds=[...new Set(saved.filter(r=>items.some(i=>i.id===r.itemId&&identity(i)===r.itemIdentity)).map(r=>r.itemId))];
 if(saved.length)return {itemId:savedIds.length===1?savedIds[0]:'',candidates:savedIds,remembered:savedIds.length===1};
 const normal=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' ');
 const sku=normal(line.sku),words=normal([line.description,line.colour,line.dimensions].join(' ')).split(/[^a-z0-9]+/).filter(w=>w.length>1);
 const exact=sku?items.filter(i=>normal(i.sku)===sku):[];
 const matches=exact.filter(i=>(!line.colour||normal(i.colour||i.color)===normal(line.colour))&&(!line.lengthMm||Number(i.lengthMm)===Number(line.lengthMm))&&(!line.dimensions||normal(i.dimensions)===normal(line.dimensions)));
 const scored=items.map(i=>{const hay=normal([i.sku,i.name,i.colour||i.color,i.dimensions,i.lengthMm].join(' '));return {item:i,score:(sku&&normal(i.sku)===sku?100:0)+words.filter(w=>hay.includes(w)).length};}).filter(v=>v.score>0).sort((a,b)=>b.score-a.score);
 return {itemId:matches.length===1?matches[0].id:'',candidates:scored.slice(0,8).map(v=>v.item.id)};
};

// Brisbane uses UTC+10 year-round; date-only deadlines must not follow the device timezone.
window.purchaseOrderToday=(now=new Date())=>new Date(now.getTime()+10*60*60*1000).toISOString().slice(0,10);
window.purchaseOrderDeliveryTiming=function(order,today=window.purchaseOrderToday()){
 const value=order.expectedDelivery||'',date=new Date(value+'T00:00:00Z');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==value)return {key:'undated',label:'Delivery date not set',date:'',days:null};
 const formatted=date.toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
 if(!['open','partial'].includes(order.status))return {key:'scheduled',label:'Expected delivery',date:formatted,days:null};
 const days=Math.round((date.getTime()-new Date(today+'T00:00:00Z').getTime())/86400000);
 return {key:days<0?'overdue':days===0?'today':days<=7?'soon':'upcoming',label:days<0?Math.abs(days)+' '+(days===-1?'day':'days')+' overdue':days===0?'Due today':days===1?'Due tomorrow':days<=7?'Due in '+days+' days':'Upcoming delivery',date:formatted,days};
};

